{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "In healthy volunteers, oral ondansetron 8 mg had about 60% absolute bioavailability versus IV; this closest analogue is directly above the 20% threshold and is corroborated by multiple human absolute-F estimates (0.56–0.65).",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Nevirapine, a high-transfer lipophilic heteroaromatic drug, has an estimated absolute oral bioavailability of about 90% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Theophylline, a high-transfer methylxanthine, has oral bioavailability fixed at 0.918 in a population PK model, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Ziprasidone, a high-transfer fused heterocycle, has absolute oral bioavailability about 60% in healthy volunteers in the fed state, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Didanosine sachet bioavailability was 17% ± 4% with food, below the 20% threshold; however, this reflects acid-labile nucleoside degradation and is not representative of the stable imidazole-carbazolone query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The closest analogue, ondansetron, has well-replicated human absolute oral bioavailability of about 56–65%, well above the 20% threshold; multiple other high-transfer drugs (theophylline, nevirapine, ziprasidone) also show high F. The only low-F evidence (didanosine) reflects acid-labile nucleoside degradation and is not representative. Therefore predict high.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement on the exact query molecule; the prediction relies on the very close ondansetron analogue and high-transfer drugs.",
    "Didanosine low-F records are formulation/condition-dependent and mechanistically mismatched, so their contradictory weight is limited."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

